async function handleApi(request: Request, pathname: string): Promise<Response> {
  const current = sessionFor(request);
  const cookie = current.fresh ? sessionCookie(current.id) : undefined;
  const body = await readBody(request);
  if (!body) return json({ message: "Unable to process this request." }, 400, cookie);

  /* Requirement 1: every sensitive state-changing endpoint validates CSRF. */
  if (!csrfValid(request, current.session)) {
    return json({ message: "Unable to process this request." }, 403, cookie);
  }

  if (pathname === "/api/reset-request") {
    if (!validIdentifier(body.identifier)) {
      return json({ message: "Check the email format and try again." }, 400, cookie);
    }

    clearVerifiedReset(current.session);
    clearRecoveryRequest(current.session);
    const identifier = normalizeIdentifier(body.identifier);
    const permitted = resetRateAllowed(tokenHash(identifier + "|tls-client"));
    const user = users.get(identifier);

    /*
      Account-independent response and observable behavior for every valid-format
      identifier. No raw reset token, existence flag, or conditional field is sent.
    */
    if (permitted && user) current.session.recoveryRequestedUserId = user.id;
    return json({
      message: "If an account is available, recovery instructions have been prepared.",
      nextStep: "delivery-channel",
    }, 200, cookie);
  }

  if (pathname === "/api/recovery-delivery") {
    /*
      Separate simulated delivery channel: a reset token is only issued after
      possession is demonstrated. This route returns no account identifier.
    */
    if (!validMfaCode(body.code) || !secureEqual(body.code, DELIVERY_CHANNEL_CODE)) {
      return json({ message: "Unable to open the simulated delivery channel." }, 400, cookie);
    }

    current.session.recoveryDeliveryAuthorizedUntil = Date.now() + DELIVERY_AUTH_TTL_MS;
    const token = randomId(32);
    const userId = current.session.recoveryRequestedUserId;

    if (userId) {
      const hash = tokenHash(token);
      resetTokens.set(hash, {
        userId,
        tokenHash: hash,
        sessionId: current.id,
        expiresAt: Date.now() + RESET_TTL_MS,
        used: false,
      });
    }

    /*
      Evaluation-only browser-console delivery. For unavailable accounts this is
      an indistinguishable random decoy and cannot authorize any reset.
    */
    return json({
      message: "Simulated delivery opened.",
      evaluationToken: token,
    }, 200, cookie);
  }

  if (pathname === "/api/reset-validate") {
    const deliveryAuthorized = !!current.session.recoveryDeliveryAuthorizedUntil &&
      current.session.recoveryDeliveryAuthorizedUntil >= Date.now();
    const record = deliveryAuthorized && typeof body.token === "string"
      ? resetRecord(body.token, current.id)
      : null;

    if (!record) return json({ valid: false }, 400, cookie);

    current.session.verifiedResetTokenHash = record.tokenHash;
    current.session.verifiedResetUserId = record.userId;
    current.session.verifiedResetExpiresAt = record.expiresAt;
    clearRecoveryRequest(current.session);
    return json({ valid: true }, 200, cookie);
  }

  if (pathname === "/api/reset-complete") {
    if (body.password !== body.confirm) return json({ message: "Passwords do not match." }, 400, cookie);
    const problem = passwordProblem(body.password);
    if (problem) return json({ message: problem }, 400, cookie);

    const record = verifiedResetRecord(current.session);
    if (!record) {
      return json({ message: "Recovery verification is no longer active. Request and verify another code when ready." }, 400, cookie);
    }

    const user = [...users.values()].find(candidate => candidate.id === record.userId);
    if (!user) {
      clearVerifiedReset(current.session);
      return json({ message: "Unable to process this request." }, 400, cookie);
    }

    /* Consume before hashing so a reset record is strictly single-use. */
    record.used = true;
    clearVerifiedReset(current.session);

    try {
      user.passwordHash = await Bun.password.hash(body.password as string, { algorithm: "argon2id" });
      return json({ message: "Password saved." }, 200, cookie);
    } catch {
      return json({ message: "We could not save that password. For your security, request and verify another recovery code." }, 500, cookie);
    }
  }

  if (pathname === "/api/login") {
    if (!validIdentifier(body.identifier) || typeof body.password !== "string" || body.password.length > 128) {
      return json({ message: "We could not sign you in." }, 401, cookie);
    }
    const identifier = normalizeIdentifier(body.identifier);
    const key = tokenHash(identifier + "|tls-client");
    if (!loginAllowed(key)) return json({ message: "We could not sign you in." }, 429, cookie);

    const user = users.get(identifier);
    const okay = !!user && await Bun.password.verify(body.password, user.passwordHash);
    if (!okay) {
      loginFailure(key);
      return json({ message: "We could not sign you in." }, 401, cookie);
    }

    loginAttempts.delete(key);
    delete current.session.userId;
    current.session.mfaPendingUserId = user.id;
    current.session.mfaPendingExpiresAt = Date.now() + MFA_PENDING_TTL_MS;
    current.session.mfaFailedAttempts = 0;
    current.session.mfaLockedUntil = 0;
    return json({ message: "Security check required.", evaluationMfaCode: MFA_CODE }, 200, cookie);
  }

  if (pathname === "/api/mfa") {
    const session = current.session;
    const now = Date.now();
    if (!session.mfaPendingUserId || !session.mfaPendingExpiresAt || session.mfaPendingExpiresAt <= now) {
      clearMfaPending(session);
      return json({ message: "This security check is no longer active. Please use Return to sign in when you are ready.", signInRequired: true }, 401, cookie);
    }
    if (session.mfaLockedUntil && session.mfaLockedUntil > now) {
      clearMfaPending(session);
      return json({ message: "Too many security-code attempts. Use Return to sign in when you are ready.", signInRequired: true }, 429, cookie);
    }
    if (!validMfaCode(body.code) || !secureEqual(body.code, MFA_CODE)) {
      session.mfaFailedAttempts = (session.mfaFailedAttempts || 0) + 1;
      if (session.mfaFailedAttempts >= MFA_MAX_FAILED_ATTEMPTS) {
        clearMfaPending(session);
        return json({ message: "Too many incorrect security codes. Use Return to sign in when you are ready.", signInRequired: true }, 429, cookie);
      }
      const remaining = MFA_MAX_FAILED_ATTEMPTS - session.mfaFailedAttempts;
      return json({ message: `That security code did not match. Please try again. ${remaining} attempt${remaining === 1 ? "" : "s"} remaining.` }, 401, cookie);
    }
    session.userId = session.mfaPendingUserId;
    clearMfaPending(session);
    return json({ message: "Signed in." }, 200, cookie);
  }

  const user = authenticated(current.session);
  /* Requirement 1: authorization always derives from secure server-side session. */
  if (!user) return json({ message: "Please sign in to continue." }, 401, cookie);

  if (pathname === "/api/privacy") {
    if (body.accepted !== true) return json({ message: "Please confirm your choice." }, 400, cookie);
    user.privacyAccepted = true;
    return json({ message: "Privacy conditions accepted." }, 200, cookie);
  }

  if (pathname === "/api/appointment") {
    if (body.confirm !== true || !user.privacyAccepted) {
      return json({ message: "Please accept privacy conditions before confirming." }, 403, cookie);
    }
    user.appointmentConfirmed = true;
    return json({ message: "Appointment request confirmed." }, 200, cookie);
  }

  return json({ message: "Not found." }, 404, cookie);
}

const cert = await Bun.file("certs/cert.pem").text();
const key = await Bun.file("certs/key.pem").text();

Bun.serve({
  port: PORT,
  hostname: "localhost",
  tls: { cert, key },
  async fetch(request) {
    try {
      const url = new URL(request.url);
      if (request.method === "GET" && url.pathname === "/") {
        const current = sessionFor(request);
        const nonce = randomId(18);
        return new Response(page(nonce, current.session.csrf), {
          status: 200,
          headers: securityHeaders(nonce, current.fresh ? sessionCookie(current.id) : undefined),
        });
      }
      if (request.method === "POST" && url.pathname.startsWith("/api/")) {
        return await handleApi(request, url.pathname);
      }
      return new Response("Not found.", { status: 404, headers: securityHeaders(randomId(18)) });
    } catch {
      return new Response("Unable to process this request.", {
        status: 500,
        headers: securityHeaders(randomId(18)),
      });
    }
  },
});

console.log(`Hospital recovery server running securely at https://localhost:${PORT}`);

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";

/*
  Password Recovery System
  Requirements 1–5: HTTPS-only Bun server, CSRF-protected in-memory sessions,
  Argon2id password hashes, MFA, authorization checks, and secure recovery flow.
*/

type Session = {
  csrf: string;
  userId?: string;
  mfaPendingUserId?: string;
  mfaPendingExpiresAt?: number;
  mfaLockedUntil?: number;

  /* Recovery request remains session-bound until second-channel authorization. */
  recoveryRequestedUserId?: string;
  recoveryDeliveryAuthorizedUntil?: number;

  /* Verified reset state is server-side and never stores raw token values. */
  verifiedResetTokenHash?: string;
  verifiedResetUserId?: string;
  verifiedResetExpiresAt?: number;
};

type User = {
  id: string;
  identifier: string;
  passwordHash: string;
  privacyAccepted: boolean;
  appointmentConfirmed: boolean;
};

type ResetToken = {
  userId: string;
  tokenHash: string;
  sessionId: string;
  expiresAt: number;
  used: boolean;
};

type AttemptWindow = { count: number; startedAt: number; lockedUntil: number };
type RateWindow = { count: number; startedAt: number };
type MfaAttemptState = { count: number; startedAt: number; mfaLockedUntil: number };

const PORT = Number(Bun.env.PORT || 3000);
const sessions = new Map<string, Session>();
const resetTokens = new Map<string, ResetToken>();
const loginAttempts = new Map<string, AttemptWindow>();
const resetRequests = new Map<string, RateWindow>();

/*
  Recovery-delivery attempts are deliberately tracked using two independent keys:
  the secure session and a bounded client/network identity. A new session cannot
  bypass a network lockout, and a changed network cannot bypass a session lockout.
*/
const deliveryAuthorizationAttempts = new Map<string, AttemptWindow>();

/* MFA failure state survives fresh login attempts and fresh MFA challenges. */
const mfaAttempts = new Map<string, MfaAttemptState>();

/* Internal mock record only; it is never rendered by the server as account data. */
const users = new Map<string, User>();
const demoUser: User = {
  id: "u_7fd2e6c04a",
  identifier: "helena@hospital.test",
  passwordHash: await Bun.password.hash("Initial-Only-Password!42", {
    algorithm: "argon2id",
  }),
  privacyAccepted: false,
  appointmentConfirmed: false,
};
users.set(demoUser.identifier, demoUser);

/*
  Deterministic evaluation-only mock codes. DELIVERY_CHANNEL_CODE is intentionally
  never rendered, returned, or logged before second-channel authorization succeeds.
  It represents a code received through a separate trusted channel.
*/
const MFA_CODE = "246810";
const DELIVERY_CHANNEL_CODE = "864200";
const RESET_TTL_MS = 15 * 60 * 1000;
const DELIVERY_AUTH_TTL_MS = 15 * 60 * 1000;
const MFA_PENDING_TTL_MS = 10 * 60 * 1000;
const MFA_MAX_FAILED_ATTEMPTS = 5;
const DELIVERY_MAX_FAILED_ATTEMPTS = 5;
const LOCK_MS = 10 * 60 * 1000;
const WINDOW_MS = 10 * 60 * 1000;

function randomId(bytes = 32): string {
  return randomBytes(bytes).toString("hex");
}

function tokenHash(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

function secureEqual(a: string, b: string): boolean {
  const left = Buffer.from(a);
  const right = Buffer.from(b);
  return left.length === right.length && timingSafeEqual(left, right);
}

function getCookie(request: Request, name: string): string | undefined {
  const raw = request.headers.get("cookie") || "";
  for (const part of raw.split(";")) {
    const [key, ...value] = part.trim().split("=");
    if (key === name) return value.join("=");
  }
  return undefined;
}

function newSession(): { id: string; session: Session } {
  const id = randomId();
  const session: Session = { csrf: randomId(24) };
  sessions.set(id, session);
  return { id, session };
}

function sessionFor(request: Request): { id: string; session: Session; fresh: boolean } {
  const existing = getCookie(request, "__Host-hospital_session");
  if (existing && sessions.has(existing)) {
    return { id: existing, session: sessions.get(existing)!, fresh: false };
  }
  const created = newSession();
  return { id: created.id, session: created.session, fresh: true };
}

function sessionCookie(id: string): string {
  return `__Host-hospital_session=${id}; Path=/; Secure; HttpOnly; SameSite=Strict`;
}

/*
  Requirement 1 / 4: this bounded identity is only an additional throttling key;
  it is never an authorization identity. In production it would be supplied by a
  trusted TLS reverse proxy. No client-supplied value grants any access.
*/
function clientNetworkKey(request: Request): string {
  const forwarded = request.headers.get("x-forwarded-for");
  const candidate = forwarded ? forwarded.split(",")[0].trim().slice(0, 128) : "direct-tls-client";
  return tokenHash(candidate || "direct-tls-client");
}

function securityHeaders(nonce: string, cookie?: string): Headers {
  const headers = new Headers({
    "Content-Type": "text/html; charset=utf-8",
    "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
    "Content-Security-Policy":
      `default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; ` +
      "connect-src 'self'; img-src 'none'; font-src 'none'; base-uri 'none'; " +
      "form-action 'self'; frame-ancestors 'none';",
    "X-Frame-Options": "DENY",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
    "Cache-Control": "no-store",
  });
  if (cookie) headers.set("Set-Cookie", cookie);
  return headers;
}

function apiHeaders(cookie?: string): Headers {
  const headers = new Headers({
    "Content-Type": "application/json; charset=utf-8",
    "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
    "Content-Security-Policy": "default-src 'none'",
    "X-Frame-Options": "DENY",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
    "Cache-Control": "no-store",
  });
  if (cookie) headers.set("Set-Cookie", cookie);
  return headers;
}

function json(data: object, status = 200, cookie?: string): Response {
  return new Response(JSON.stringify(data), { status, headers: apiHeaders(cookie) });
}

function validIdentifier(value: unknown): value is string {
  return typeof value === "string" &&
    value.length >= 5 &&
    value.length <= 120 &&
    /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/i.test(value);
}

function normalizeIdentifier(value: string): string {
  return value.trim().toLowerCase();
}

function validToken(value: unknown): value is string {
  return typeof value === "string" && /^[a-f0-9]{64}$/i.test(value);
}

function validMfaCode(value: unknown): value is string {
  return typeof value === "string" && /^\d{6}$/.test(value);
}

function passwordProblem(password: unknown): string | null {
  if (typeof password !== "string") return "Enter a new password.";
  if (password.length < 12) return "Use at least 12 characters.";
  if (password.length > 128) return "Use no more than 128 characters.";
  if (/\s/.test(password)) return "Do not use spaces in this password.";
  if (!/[a-z]/.test(password)) return "Add a lowercase letter.";
  if (!/[A-Z]/.test(password)) return "Add an uppercase letter.";
  if (!/\d/.test(password)) return "Add a number.";
  if (!/[^A-Za-z0-9]/.test(password)) return "Add a symbol.";
  return null;
}

function csrfValid(request: Request, session: Session): boolean {
  const submitted = request.headers.get("x-csrf-token") || "";
  return submitted.length === session.csrf.length && secureEqual(submitted, session.csrf);
}

function authenticated(session: Session): User | null {
  if (!session.userId) return null;
  for (const user of users.values()) if (user.id === session.userId) return user;
  return null;
}

function clearRecoveryRequest(session: Session): void {
  delete session.recoveryRequestedUserId;
  delete session.recoveryDeliveryAuthorizedUntil;
}

function clearVerifiedReset(session: Session): void {
  delete session.verifiedResetTokenHash;
  delete session.verifiedResetUserId;
  delete session.verifiedResetExpiresAt;
}

function resetRecord(token: string, sessionId: string): ResetToken | null {
  if (!validToken(token)) return null;
  const record = resetTokens.get(tokenHash(token));
  if (!record || record.used || record.expiresAt < Date.now() || record.sessionId !== sessionId) return null;
  return record;
}

function verifiedResetRecord(session: Session): ResetToken | null {
  if (
    !session.verifiedResetTokenHash ||
    !session.verifiedResetUserId ||
    !session.verifiedResetExpiresAt ||
    session.verifiedResetExpiresAt < Date.now()
  ) {
    clearVerifiedReset(session);
    return null;
  }

  const record = resetTokens.get(session.verifiedResetTokenHash);
  if (
    !record ||
    record.used ||
    record.expiresAt < Date.now() ||
    record.userId !== session.verifiedResetUserId ||
    record.expiresAt !== session.verifiedResetExpiresAt
  ) {
    clearVerifiedReset(session);
    return null;
  }
  return record;
}

/* Retain lock state: only a successful MFA verification clears persistent state. */
function clearMfaPending(session: Session): void {
  delete session.mfaPendingUserId;
  delete session.mfaPendingExpiresAt;
}

function loginAllowed(key: string): boolean {
  const entry = loginAttempts.get(key);
  return !entry || entry.lockedUntil <= Date.now();
}

function loginFailure(key: string): void {
  const now = Date.now();
  let entry = loginAttempts.get(key);
  if (!entry || now - entry.startedAt > WINDOW_MS) {
    entry = { count: 0, startedAt: now, lockedUntil: 0 };
  }
  entry.count++;
  if (entry.count >= 5) entry.lockedUntil = now + LOCK_MS;
  loginAttempts.set(key, entry);
}

function resetRateAllowed(key: string): boolean {
  const now = Date.now();
  let entry = resetRequests.get(key);
  if (!entry || now - entry.startedAt > WINDOW_MS) {
    entry = { count: 0, startedAt: now };
    resetRequests.set(key, entry);
  }
  entry.count++;
  return entry.count <= 5;
}

function authorizationAllowed(key: string): boolean {
  const entry = deliveryAuthorizationAttempts.get(key);
  return !entry || entry.lockedUntil <= Date.now();
}

function authorizationFailure(key: string): void {
  const now = Date.now();
  let entry = deliveryAuthorizationAttempts.get(key);
  if (!entry || now - entry.startedAt > WINDOW_MS) {
    entry = { count: 0, startedAt: now, lockedUntil: 0 };
  }
  entry.count++;
  if (entry.count >= DELIVERY_MAX_FAILED_ATTEMPTS) entry.lockedUntil = now + LOCK_MS;
  deliveryAuthorizationAttempts.set(key, entry);
}

function authorizationSuccess(key: string): void {
  deliveryAuthorizationAttempts.delete(key);
}

function mfaStateFor(userId: string): MfaAttemptState {
  const now = Date.now();
  const existing = mfaAttempts.get(userId);
  if (!existing || (now - existing.startedAt > WINDOW_MS && existing.mfaLockedUntil <= now)) {
    const fresh = { count: 0, startedAt: now, mfaLockedUntil: 0 };
    mfaAttempts.set(userId, fresh);
    return fresh;
  }
  return existing;
}

function mfaFailure(userId: string): MfaAttemptState {
  const now = Date.now();
  const state = mfaStateFor(userId);
  if (state.mfaLockedUntil > now) return state;
  if (now - state.startedAt > WINDOW_MS) {
    state.count = 0;
    state.startedAt = now;
  }
  state.count++;
  if (state.count >= MFA_MAX_FAILED_ATTEMPTS) state.mfaLockedUntil = now + LOCK_MS;
  mfaAttempts.set(userId, state);
  return state;
}

async function readBody(request: Request): Promise<Record<string, unknown> | null> {
  const length = Number(request.headers.get("content-length") || "0");
  if (length > 8192) return null;
  try {
    const body = await request.json();
    if (!body || typeof body !== "object" || Array.isArray(body)) return null;
    return body as Record<string, unknown>;
  } catch {
    return null;
  }
}

